"""
Alembic environment for the app's SQLite database.

* The app runs `upgrade head` at startup (backend.models.database.upgrade_db),
  handing its own connection in via config.attributes["connection"].
* From the CLI the database is backend.config.get_db_path(), or `-x db=<file>`.
* render_as_batch: SQLite can't ALTER most column properties, so autogenerated
  migrations use batch mode (copy-and-swap the table).
"""
from alembic import context
from sqlalchemy import create_engine

from backend.models.database import Base
import backend.models.tables  # noqa: F401  (registers every model on Base.metadata)

config = context.config
target_metadata = Base.metadata


def _url() -> str:
    db = context.get_x_argument(as_dictionary=True).get("db")
    if not db:
        from backend.config import get_db_path

        db = str(get_db_path())
    return f"sqlite:///{db}"


def _configure(connection) -> None:
    context.configure(
        connection=connection,
        target_metadata=target_metadata,
        render_as_batch=True,
        compare_type=True,
    )


def run_migrations_offline() -> None:
    context.configure(url=_url(), target_metadata=target_metadata, literal_binds=True,
                      render_as_batch=True, dialect_opts={"paramstyle": "named"})
    with context.begin_transaction():
        context.run_migrations()


def run_migrations_online() -> None:
    connection = config.attributes.get("connection")
    if connection is not None:
        _configure(connection)
        with context.begin_transaction():
            context.run_migrations()
        return
    engine = create_engine(_url())
    with engine.connect() as connection:
        _configure(connection)
        with context.begin_transaction():
            context.run_migrations()
    engine.dispose()


if context.is_offline_mode():
    run_migrations_offline()
else:
    run_migrations_online()
